        private void GumpEditorCreateResolutionSelector()
        {
            if (GumpEditorResolutionSelector != null)
                return;

            GumpEditorResolutionSelector =
                new System.Windows.Forms.ComboBox();

            GumpEditorResolutionSelector.Name =
                "GumpEditorResolutionSelector";

            GumpEditorResolutionSelector.DropDownStyle =
                System.Windows.Forms.ComboBoxStyle.DropDownList;

            GumpEditorResolutionSelector.Width = 125;

            GumpEditorResolutionSelector.Items.Clear();

            foreach (var resolution in
                     GumpEditorResolutions)
            {
                GumpEditorResolutionSelector.Items.Add(
                    resolution.Name);
            }

            GumpEditorResolutionSelector.SelectedIndexChanged +=
                GumpEditorResolutionSelector_SelectedIndexChanged;

            GumpEditorResolutionSelector.SelectedIndex = 0;
        }

        private void GumpEditorResolutionSelector_SelectedIndexChanged(
            object sender,
            System.EventArgs e)
        {
            if (GumpEditorResolutionSelector == null)
                return;

            int index =
                GumpEditorResolutionSelector.SelectedIndex;

            if (index < 0 ||
                index >= GumpEditorResolutions.Length)
            {
                return;
            }

            var resolution =
                GumpEditorResolutions[index];

            if (_canvas == null)
                return;

            _canvas.ViewportWidth =
                resolution.Width;

            _canvas.ViewportHeight =
                resolution.Height;

            _canvas.Invalidate();
        }

