private Button CreateTextButton(
    string text,
    string tooltip)
{
    var button =
        new Button
        {
            Text = text,
            Width = 38,
            Height = 28,
            FlatStyle =
                FlatStyle.Standard
        };

    var tip =
        new ToolTip();

    tip.SetToolTip(
        button,
        tooltip);

    return button;
}

private void TextFontComboDrawItem(
    object sender,
    DrawItemEventArgs e)
{
    if (e.Index < 0)
        return;

    e.DrawBackground();

    string label =
        "Font " + e.Index;

    if (_uoFontReader != null)
    {
        Bitmap preview =
            _uoFontReader.RenderText(
                e.Index,
                "AaBbCc 0123456789",
                Color.White,
                1.0f);

        if (preview != null)
        {
            Rectangle rect =
                new Rectangle(
                    e.Bounds.X + 4,
                    e.Bounds.Y + 2,
                    Math.Min(
                        preview.Width,
                        190),
                    Math.Min(
                        preview.Height,
                        e.Bounds.Height - 4));

            e.Graphics.DrawImage(
                preview,
                rect);

            preview.Dispose();
        }
    }

    using (var brush =
           new SolidBrush(
               e.ForeColor))
    {
        e.Graphics.DrawString(
            label,
            e.Font,
            brush,
            e.Bounds.Right - 52,
            e.Bounds.Y + 7);
    }

    e.DrawFocusRectangle();
}

private void TextFontComboChanged(
    object sender,
    EventArgs e)
{
    UpdateTextFontPreview();

    UpdateTextEditorHtmlFont();

    _canvas.RefreshCanvas();
}

private void TextFormattingChanged(
    object sender,
    EventArgs e)
{
    ApplyFormattingToHtml();

    _canvas.RefreshCanvas();
}

private void TextEditorChanged(
    object sender,
    EventArgs e)
{
    UpdateTextFontPreview();
}

private void UpdateTextFontPreview()
{
    if (_textFontPreview == null ||
        _uoFontReader == null ||
        _textFontCombo == null)
        return;

    int fontId =
        Math.Max(
            0,
            _textFontCombo.SelectedIndex);

    Bitmap preview =
        _uoFontReader.RenderText(
            fontId,
            "AaBbCc 0123456789",
            Color.White,
            1.0f);

    Image old =
        _textFontPreview.Image;

    _textFontPreview.Image =
        preview;

    if (old != null)
        old.Dispose();

    if (_textFontInfo != null)
    {
        _textFontInfo.Text =
