        private sealed class GumpUndoSnapshot
        {
            public int Width;
            public int Height;
            public int CurrentPage;
            public List<GumpElement> Elements =
                new List<GumpElement>();
        }

        private readonly Stack<GumpUndoSnapshot> _gumpUndo =
            new Stack<GumpUndoSnapshot>();

        private bool _restoringUndo;

        private void SaveUndoSnapshot()
        {
            if (_restoringUndo)
                return;

            if (_canvas == null ||
                _canvas.Document == null)
                return;

            var document =
                _canvas.Document;

            var snapshot =
                new GumpUndoSnapshot();

            snapshot.Width =
                document.Width;

            snapshot.Height =
                document.Height;

            snapshot.CurrentPage =
                document.CurrentPage;

            foreach (GumpElement source in document.Elements)
            {
                var copy =
                    new GumpElement();

                copy.Type =
                    source.Type;

                copy.CommandName =
                    source.CommandName;

                copy.X =
                    source.X;

                copy.Y =
                    source.Y;

                copy.Width =
                    source.Width;

                copy.Height =
                    source.Height;

                copy.Hue =
                    source.Hue;

                copy.Text =
                    source.Text;

                copy.ArtId =
                    source.ArtId;

                copy.ButtonId =
                    source.ButtonId;

                copy.Page =
                    source.Page;

                copy.SourceLine =
                    source.SourceLine;

                copy.SourceCode =
                    source.SourceCode;

                copy.Font =
                    source.Font;

                copy.TextSize =
                    source.TextSize;

                copy.TextAlign =
                    source.TextAlign;

                copy.Bold =
                    source.Bold;

                copy.Italic =
                    source.Italic;

                copy.Underline =
                    source.Underline;

                foreach (string parameter in source.Parameters)
                {
                    copy.Parameters.Add(parameter);
                }

                snapshot.Elements.Add(copy);
            }

            _gumpUndo.Push(snapshot);

            while (_gumpUndo.Count > 100)
            {
                var temp =
                    _gumpUndo.ToArray();

                _gumpUndo.Clear();

                for (int i = 0;
                     i < temp.Length - 1;
                     i++)
                {
                    _gumpUndo.Push(temp[i]);
                }
            }
        }

        private void UndoLastChange()
        {
            if (_restoringUndo)
                return;

            if (_gumpUndo.Count == 0)
            {
                System.Media.SystemSounds.Beep.Play();
                return;
            }

            if (_canvas == null ||
                _canvas.Document == null)
                return;

            var snapshot =
                _gumpUndo.Pop();

            _restoringUndo = true;

            try
            {
                var document =
                    _canvas.Document;

                document.Width =
                    snapshot.Width;

                document.Height =
                    snapshot.Height;

                document.CurrentPage =
                    snapshot.CurrentPage;

                document.Elements.Clear();

                foreach (GumpElement source in snapshot.Elements)
                {
                    var copy =
                        new GumpElement();

                    copy.Type =
                        source.Type;

                    copy.CommandName =
                        source.CommandName;

                    copy.X =
                        source.X;

                    copy.Y =
                        source.Y;

                    copy.Width =
                        source.Width;

                    copy.Height =
                        source.Height;

                    copy.Hue =
                        source.Hue;

                    copy.Text =
                        source.Text;

                    copy.ArtId =
                        source.ArtId;

                    copy.ButtonId =
                        source.ButtonId;

                    copy.Page =
                        source.Page;

                    copy.SourceLine =
                        source.SourceLine;

                    copy.SourceCode =
                        source.SourceCode;

                    copy.Font =
                        source.Font;

                    copy.TextSize =
                        source.TextSize;

                    copy.TextAlign =
                        source.TextAlign;

                    copy.Bold =
                        source.Bold;

                    copy.Italic =
                        source.Italic;

                    copy.Underline =
                        source.Underline;

                    foreach (string parameter in source.Parameters)
                    {
                        copy.Parameters.Add(parameter);
                    }

                    document.Elements.Add(copy);
                }

                document.IsModified =
                    true;

                _canvas.ClearSelection();

                PopulatePages();

                PopulateElements();

                UpdateProperties();

                UpdateStatus();

                _canvas.RefreshCanvas();
            }
            finally
            {
                _restoringUndo = false;
            }
        }



