        private void InitializeProperties()
        {
            _propertiesPanel = new Panel
            {
                Dock = DockStyle.Right,
                Width = 330,
                Padding = new Padding(10),
                BackColor = Color.FromArgb(35, 35, 38)
            };

            var tabs = new TabControl
            {
                Dock = DockStyle.Fill
            };

            var propertiesTab = new TabPage("Propriedades");
            var artTab = new TabPage("Artes");
            var huesTab = new TabPage("Hues");

            propertiesTab.BackColor =
                Color.FromArgb(35, 35, 38);

            artTab.BackColor =
                Color.FromArgb(35, 35, 38);

            huesTab.BackColor =
                Color.FromArgb(35, 35, 38);

            BuildPropertiesTab(propertiesTab);
            BuildArtTab(artTab);
            BuildHuesTab(huesTab);

            tabs.TabPages.Add(propertiesTab);
            tabs.TabPages.Add(artTab);
            tabs.TabPages.Add(huesTab);

            _propertiesPanel.Controls.Add(tabs);
        }

        private void AddNewGumpPage(
            object sender,
            EventArgs e)
        {
            if (_canvas == null ||
                _canvas.Document == null)
            {
                MessageBox.Show(
                    this,
                    "Abra um Gump primeiro.",
                    "Gump Editor",
                    MessageBoxButtons.OK,
                    MessageBoxIcon.Information);

                return;
            }

            int nextPage = 1;

            foreach (int page
                     in _canvas.Document.GetPages())
            {
                if (page >= nextPage)
                    nextPage = page + 1;
            }

            var element =
                new GumpElement
                {
                    Type =
                        GumpElementType.Page,

                    CommandName =
                        "AddPage",

                    Page =
                        nextPage,

                    SourceLine =
                        0,

                    SourceCode =
                        string.Empty
                };

            element.Parameters.Add(
                nextPage.ToString(
                    System.Globalization.CultureInfo.InvariantCulture));

            _canvas.Document.AddElement(
                element);

            _canvas.Document.CurrentPage =
                nextPage;

            _canvas.Document.IsModified =
                true;

            PopulatePages();
            PopulateElements();
            _canvas.ClearSelection();
            UpdateProperties();
            UpdateStatus();
            _canvas.Invalidate();
        }

        private void ToggleTestMode(
            object sender,
            EventArgs e)
        {
            if (_canvas == null)
                return;

            bool enabled =
                _testButton != null &&
                _testButton.Checked;

            _canvas.TestMode =
                enabled;

            if (enabled)
            {
                _canvas.ClearSelection();
                _canvas.Cursor =
                    Cursors.Hand;
            }
            else
            {
                _canvas.Cursor =
                    Cursors.Default;
            }

            _canvas.Invalidate();
        }

        private void ButtonActionChanged(
            object sender,
            EventArgs e)
        {
            if (_buttonActionCombo == null ||
                _buttonTargetPage == null)
            {
                return;
            }

            _buttonTargetPage.Enabled =
                _buttonActionCombo.SelectedIndex == 1;
        }

        private void LoadButtonLinkProperties(
            GumpElement element)
        {
            if (_buttonActionCombo == null ||
                _buttonTargetPage == null)
            {
                return;
            }

            if (element == null ||
                element.Type !=
                GumpElementType.Button)
            {
                _buttonActionCombo.SelectedIndex = 0;
                _buttonTargetPage.Value = 0;

                _buttonActionCombo.Enabled = false;
                _buttonTargetPage.Enabled = false;

                return;
            }

            _buttonActionCombo.Enabled = true;

            string buttonType =
                "GumpButtonType.Reply";

            string parameter =
                "0";

            if (element.Parameters != null &&
                element.Parameters.Count > 5 &&
                !string.IsNullOrWhiteSpace(
                    element.Parameters[5]))
            {
                buttonType =
                    element.Parameters[5];
            }

            if (element.Parameters != null &&
                element.Parameters.Count > 6 &&
                !string.IsNullOrWhiteSpace(
                    element.Parameters[6]))
            {
                parameter =
                    element.Parameters[6];
            }

            if (buttonType.IndexOf(
                    "GumpButtonType.Page",
                    StringComparison.OrdinalIgnoreCase) >= 0)
            {
                _buttonActionCombo.SelectedIndex = 1;

                int page;

                if (!int.TryParse(
                        parameter,
                        out page))
                {
                    page = 0;
                }

                page =
                    Math.Max(
                        0,
                        Math.Min(
                            10000,
                            page));

                _buttonTargetPage.Value =
                    page;

                _buttonTargetPage.Enabled =
                    true;
            }
            else if (buttonType.IndexOf(
                         "GumpButtonType.Close",
                         StringComparison.OrdinalIgnoreCase) >= 0)
            {
                _buttonActionCombo.SelectedIndex = 2;
                _buttonTargetPage.Value = 0;
                _buttonTargetPage.Enabled = false;
            }
            else
            {
                _buttonActionCombo.SelectedIndex = 0;
                _buttonTargetPage.Value = 0;
                _buttonTargetPage.Enabled = false;
            }
        }


