        private static NumericUpDown Number(int value = 0)
        {
            return new NumericUpDown
            {
                Minimum = -10000,
                Maximum = 10000,
                Value = value,
                Dock = DockStyle.Fill
            };
        }

        private static void AddPropertyRow(
            TableLayoutPanel panel,
            string caption,
            Control control,
            int row)
        {
            panel.RowStyles.Add(
                new RowStyle(SizeType.AutoSize));

            panel.Controls.Add(
                new Label
                {
                    Text = caption,
                    ForeColor = Color.White,
                    Dock = DockStyle.Fill,
                    TextAlign =
                        ContentAlignment.MiddleLeft,
                    Padding =
                        new Padding(0, 5, 0, 5)
                },
                0,
                row);

            panel.Controls.Add(
                control,
                1,
                row);
        }

