        protected override bool ProcessCmdKey(
            ref Message msg,
            Keys keyData)
        {
            // GUMPEDITOR_UNDO_KEY_FINAL
            if (keyData == (Keys.Control | Keys.Z))
            {
                UndoLastChange();
                return true;
