        private void ApplyButtonMouseDown(
            object sender,
            MouseEventArgs e)
        {
            if (sender is Button button &&
                e.Button == MouseButtons.Left)
            {
                button.BackColor =
                    SystemColors.ControlDark;

                button.ForeColor =
                    SystemColors.ControlText;

                button.FlatStyle =
                    FlatStyle.Flat;
            }
        }

        private void ApplyButtonMouseUp(
            object sender,
            MouseEventArgs e)
        {
            if (sender is Button button &&
                e.Button == MouseButtons.Left)
            {
                button.BackColor =
                    SystemColors.Control;

                button.ForeColor =
                    SystemColors.ControlText;

                button.FlatStyle =
                    FlatStyle.Standard;
            }
        }
        private void ApplyProperties(
            object sender,
            EventArgs e)
        {
            var element =
                _canvas.SelectedElement;

            if (element == null)
                return;

            element.X =
                (int)_x.Value;

            element.Y =
                (int)_y.Value;

            element.Width =
                Math.Max(
                    1,
                    (int)_width.Value);

            element.Height =
                Math.Max(
                    1,
                    (int)_height.Value);

            element.ArtId =
                Math.Max(
                    0,
                    (int)_art.Value);

            element.ButtonId =
                Math.Max(
                    0,
                    (int)_button.Value);

            element.Hue =
                Math.Max(
                    0,
                    (int)_hue.Value);

            element.Text =
                _text.Text ??
                string.Empty;

            // ====================================================
            // PARAMETROS DO AddButton
            //
            // [5] = GumpButtonType
            // [6] = parametro
            // ====================================================
            if (element.Type ==
                GumpElementType.Button)
            {
                while (
                    element.Parameters.Count <= 6)
                {
                    element.Parameters.Add(
                        "0");
                }

                int action =
                    _buttonActionCombo == null
                        ? 0
                        : _buttonActionCombo.SelectedIndex;

                int targetPage =
                    _buttonTargetPage == null
                        ? 0
                        : (int)_buttonTargetPage.Value;

                if (action == 1)
                {
                    element.Parameters[5] =
                        "GumpButtonType.Page";

                    element.Parameters[6] =
                        targetPage.ToString(
                            System.Globalization.CultureInfo.InvariantCulture);
                }
                else if (action == 2)
                {
                    element.Parameters[5] =
                        "GumpButtonType.Close";

                    element.Parameters[6] =
                        "0";
                }
                else
                {
                    element.Parameters[5] =
                        "GumpButtonType.Reply";

                    element.Parameters[6] =
                        "0";
                }
            }

            _canvas.Document.IsModified =
                true;

            _canvas.ClearArtCache();

            _canvas.Invalidate();

            PopulateElements();

            SelectElementInList(
                element);

            UpdateProperties();

            UpdateStatus();
        }

        private void CanvasSelectedElementChanged(
            object sender,
            EventArgs e)
        {
            UpdateProperties();
            SelectElementInList(
                _canvas.SelectedElement);
            UpdateStatus();
        }

        private void UpdateProperties()
        {
            var element =
                _canvas.SelectedElement;

            if (element == null)
            {
                _selectedLabel.Text =
                    "Nenhum elemento";

                _x.Value = 0;
                _y.Value = 0;
                _width.Value = 1;
                _height.Value = 1;
                _art.Value = 0;
                _button.Value = 1;
                _hue.Value = 0;
                _text.Text =
                    string.Empty;

                LoadButtonLinkProperties(
                    null);

                return;
            }

            _selectedLabel.Text =
                element.Type +
                " | Linha " +
                element.SourceLine;

            SetValue(
                _x,
                element.X);

            SetValue(
                _y,
                element.Y);

            SetValue(
                _width,
                Math.Max(
                    1,
                    element.Width));

            SetValue(
                _height,
                Math.Max(
                    1,
                    element.Height));

            SetValue(
                _art,
                element.ArtId);

            SetValue(
                _button,
                element.ButtonId);

            SetValue(
                _hue,
                element.Hue);

            _text.Text =
                element.Text ??
                string.Empty;

            if (_artBrowserId != null)
            {
                _artBrowserId.Value =
                    Math.Max(
                        _artBrowserId.Minimum,
                        Math.Min(
                            _artBrowserId.Maximum,
                            element.ArtId));
            }

            if (_artBrowserHue != null)
            {
                _artBrowserHue.Value =
                    Math.Max(
                        _artBrowserHue.Minimum,
                        Math.Min(
                            _artBrowserHue.Maximum,
                            element.Hue));
            }

            LoadButtonLinkProperties(
                element);
        }

        private static void SetValue(
            NumericUpDown control,
            int value)
        {
            if (value < control.Minimum)
                value = (int)control.Minimum;

            if (value > control.Maximum)
                value = (int)control.Maximum;

            control.Value = value;
        }

        private void PreviewArt(
            object sender,
            EventArgs e)
        {
            if (_gumpArtReader == null)
            {
                MessageBox.Show(
                    this,
