}
private void LoadSelectedElementIntoTextEditor()
{
    if (_canvas == null ||
        _gumpTextEditorPanel == null)
    {
        return;
    }

    GumpElement element =
        _canvas.SelectedElement;

    if (element == null)
    {
        _gumpTextEditorPanel.Visible = true;
        return;
    }

    string typeName =
        element.GetType().Name;

    bool isText =
        typeName.IndexOf(
            "Label",
            StringComparison.OrdinalIgnoreCase) >= 0
        ||
        typeName.IndexOf(
            "Text",
            StringComparison.OrdinalIgnoreCase) >= 0
        ||
        typeName.IndexOf(
            "Html",
            StringComparison.OrdinalIgnoreCase) >= 0;

    if (!isText)
    {
        _gumpTextEditorPanel.Visible = true;
        return;
    }

    _gumpTextEditorPanel.Visible = true;

    // --------------------------------------------------------
    // TEXTO
    // --------------------------------------------------------

    _gumpTextEditor.Text =
        element.Text ??
        string.Empty;

    // --------------------------------------------------------
    // FONTE UO
    // --------------------------------------------------------

    int fontId =
        element.Font;

    if (fontId < 0 ||
        _uoFontReader == null ||
        fontId >= _uoFontReader.Fonts.Count)
    {
        fontId = 0;
    }

    if (_gumpFontCombo != null &&
        fontId < _gumpFontCombo.Items.Count)
    {
        _gumpFontCombo.SelectedIndex =
            fontId;
    }

    _selectedUoFont =
        fontId;

    if (_gumpFontInfo != null)
    {
        _gumpFontInfo.Text =
