    int size = 12;

    if (_gumpSizeCombo != null &&
        _gumpSizeCombo.SelectedItem != null)
    {
        int.TryParse(
            _gumpSizeCombo.SelectedItem.ToString(),
            out size);

        if (size <= 0)
            size = 12;
    }

    element.TextSize =
        size;

